// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address to, uint256 amount) public {
        // Ensure the call to XBornID() sets up the owner's balance
        // Owner is msg.sender in constructor, we need to simulate a call from owner
        address owner = address(c); // not needed, just use the contract deployer
        // To call XBornID() we need to be the owner (deployer)
        // But we can also just test the transfer function directly after deployment
        // Since XBornID() requires msg.sender == owner, we call it from the test contract
        // which is the deployer

        // Deployer has totalDistributed balance after XBornID()
        // We need to ensure amount <= deployer's balance
        // Use bound to ensure amount is within reasonable range
        vm.assume(amount <= c.balanceOf(address(this)));
        vm.assume(to != address(0));

        bool success = c.transfer(to, amount);
        assertTrue(success);
    }
}

